vec2 R;
#define Main void mainImage(out vec4 Q, in vec2 U) {R = iResolution.xy;
#define A(u) texture(iChannel0,(u)/R)
#define B(u) texture(iChannel1,(u)/R)
#define C(u) texture(iChannel2,(u)/R)
#define D(u) texture(iChannel3,(u)/R)

#define vel(v) v*inversesqrt(1.+dot(v,v))

 #define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))

 vec4 hash(vec4 p4)
{
    p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}

Main 
    Q = vec4(0);
        vec2 V = vec2(0);
        for (float x = -2.;x <= 2.; x++)
        for (float y = -2.;y <= 2.; y++) {

            vec2 u = vec2(x,y);

            vec4 q = A(U+u);
            vec4 b = B(U+u);
            vec2 v = unpackSnorm2x16(uint(q.z));
            float k = 1.7;
            vec2 t = vel(q.xy);
            vec4 o = clamp(v.xyxy+t.xyxy+u.xyxy+k*vec4(-.5,-.5,.5,.5),-.5,.5);
            float w = (o.z-o.x)*(o.w-o.y)/k/k;
            v.xy = 0.5*(o.xy+o.zw);
            V.xy += v.xy*q.w*w;
            Q.xy += q.xy*q.w*w;
            Q.w += q.w*w;
            u = u+v.xy;
             float l = length(u);
             if (l>0.) {
                 float r = exp(-.2*dot(u,u))/length(u);
                Q.xy  -= .001*(q.w+b.x)*u*r;
             }
        }
        if (Q.w>0.) {
            Q.xy/=Q.w;
            V /= Q.w;
        }
        Q.xy *= .99;
        Q.xy -= .001*normalize(U-.5*R+.1);
        Q.w += .00001;
        if (Q.w>10.) Q.w = 10.;
        if (length(U-.5*R)<10.) Q.w *= 0.;
        if (length(Q.xy)>1.) Q.xy = 1.*normalize(Q.xy);
        if(U.y < 1.||U.x<1.||R.x-U.x<1.||R.y-U.y<1.) Q *= 0.;
        Q.z = float(packSnorm2x16(V.xy));

}

